//! MONEY IS AN INTEGER COUNT OF MINOR UNITS, NEVER A FLOAT.
//!
//! `0.1 + 0.2` is not a rounding curiosity in a currency: it is a balance that disagrees with itself
//! and a total that fails reconciliation for reasons nobody can see in the numbers. The Rust half of
//! the rule the `finance-money.ts` record states for the frontend — same model, same guarantee, so a
//! figure means the same thing whichever side computes it.

/// A signed amount in minor units — cents for USD. Currency is carried alongside by the row.
pub type Minor = i64;

/// Parse a human-written amount into MINOR UNITS, without ever constructing a float.
///
/// Statements write money a dozen ways and every one of them appears in the four institutions this
/// targets: `1234.56`, `$1,234.56`, `-1234.56`, `(1234.56)` for a credit, `1234.56-` trailing-sign,
/// and a bare `1234` meaning whole units.
///
/// PARSED AS TEXT, DIGIT BY DIGIT. `"0.07".parse::<f64>() * 100.0` is `7.000000000000001`, and
/// rounding that back is a coin flip on the boundary — so the fractional part is read as an integer
/// and scaled, and the value is exact by construction.
pub fn parse_minor(raw: &str) -> Result<Minor, String> {
    let t = raw.trim();
    if t.is_empty() {
        return Err("empty amount".into());
    }
    // Accounting parentheses mean negative, and may wrap the sign or the symbol.
    let (t, paren) = match (t.strip_prefix('('), t.strip_suffix(')')) {
        (Some(inner), _) if t.ends_with(')') => (inner.trim_end_matches(')'), true),
        _ => (t, false),
    };
    // A TRAILING sign is a real convention (`1234.56-`), and reading it as a stray character would
    // silently flip a refund into a charge.
    let (t, trailing_neg) = match t.strip_suffix('-') {
        Some(rest) => (rest.trim(), true),
        None => (t, false),
    };
    let mut neg = paren || trailing_neg;

    let mut digits = String::new();
    let mut frac: Option<String> = None;
    for c in t.chars() {
        match c {
            '-' if digits.is_empty() && frac.is_none() => neg = true,
            '+' => {}
            '.' => {
                if frac.is_some() {
                    return Err(format!("more than one decimal point in {raw:?}"));
                }
                frac = Some(String::new());
            }
            // Thousands separators and the currency symbol carry no value.
            ',' | ' ' | '\u{a0}' | '$' | '£' | '€' => {}
            c if c.is_ascii_digit() => match frac {
                Some(ref mut f) => f.push(c),
                None => digits.push(c),
            },
            c => return Err(format!("unexpected {c:?} in amount {raw:?}")),
        }
    }
    if digits.is_empty() && frac.as_ref().map(|f| f.is_empty()).unwrap_or(true) {
        return Err(format!("no digits in amount {raw:?}"));
    }
    let whole: i64 = if digits.is_empty() { 0 } else { digits.parse().map_err(|_| format!("amount out of range: {raw:?}"))? };

    // Exactly two minor digits, whatever was written. A third is truncated rather than rounded: a
    // statement that prints three has a sub-cent artifact, and inventing a cent from it would put a
    // figure in the store that is not on the statement.
    let cents: i64 = match frac {
        None => 0,
        Some(f) => {
            let f = f.as_str();
            match f.len() {
                0 => 0,
                1 => f.parse::<i64>().map_err(|_| "bad fraction")? * 10,
                _ => f[..2].parse::<i64>().map_err(|_| "bad fraction")?,
            }
        }
    };
    let minor = whole
        .checked_mul(100)
        .and_then(|w| w.checked_add(cents))
        .ok_or_else(|| format!("amount out of range: {raw:?}"))?;
    Ok(if neg { -minor } else { minor })
}

/// Render minor units back for display. Never feed this into arithmetic.
pub fn format_minor(minor: Minor) -> String {
    let sign = if minor < 0 { "-" } else { "" };
    let a = minor.abs();
    format!("{sign}{}.{:02}", a / 100, a % 100)
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// THE ALGEBRA — ported from `@/features/finance/lib/money`.
//
// The analysis half of this feature was written in TypeScript against a `Money` that CARRIES ITS
// CURRENCY, and the guard that buys is not decorative: `reconcile` refuses a foreign-currency row
// rather than adding it, and `position` excludes a foreign account rather than converting it. A port
// to a bare `i64` would drop both silently, so the currency comes along.
//
// It comes along CHEAPLY. `Currency` is three bytes, `Copy`, and compared by value — no allocation,
// no lifetime, and a mismatch is a compile-time-shaped error rather than a string comparison nobody
// runs.

/// An ISO-4217-shaped code. Three bytes, `Copy`, compared exactly — this module never converts.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Currency([u8; 3]);

impl Currency {
    /// Uppercased on the way in, so `usd` and `USD` are the same currency rather than two.
    pub fn new(code: &str) -> Result<Currency, String> {
        let b = code.as_bytes();
        if b.len() != 3 || !b.iter().all(|c| c.is_ascii_alphabetic()) {
            return Err(format!("`{code}` is not a three-letter currency code"));
        }
        Ok(Currency([b[0].to_ascii_uppercase(), b[1].to_ascii_uppercase(), b[2].to_ascii_uppercase()]))
    }

    pub const USD: Currency = Currency(*b"USD");

    pub fn as_str(&self) -> &str {
        std::str::from_utf8(&self.0).unwrap_or("???")
    }
}

impl std::fmt::Display for Currency {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// A signed count of MINOR UNITS, with the currency it is in.
///
/// `0.1 + 0.2 == 0.30000000000000004` is the whole reason this is an integer. In a currency that is
/// not a rounding curiosity: it is a balance that disagrees with itself and a total that fails
/// reconciliation for reasons nobody can see in the numbers.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Money {
    pub minor: Minor,
    pub currency: Currency,
}

/// Adding USD to EUR is not a number problem, it is a modelling error — and returning a number would
/// let it travel.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CurrencyMismatch {
    pub left: Currency,
    pub right: Currency,
}

impl std::fmt::Display for CurrencyMismatch {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "cannot combine {} with {} — convert first, explicitly", self.left, self.right)
    }
}

pub fn money(minor: Minor, currency: Currency) -> Money {
    Money { minor, currency }
}

/// USD, for the overwhelmingly common case — named so the assumption is visible at the call site.
pub fn usd(minor: Minor) -> Money {
    Money { minor, currency: Currency::USD }
}

fn same(a: Money, b: Money) -> Result<(), CurrencyMismatch> {
    if a.currency == b.currency {
        Ok(())
    } else {
        Err(CurrencyMismatch { left: a.currency, right: b.currency })
    }
}

pub fn add(a: Money, b: Money) -> Result<Money, CurrencyMismatch> {
    same(a, b)?;
    Ok(Money { minor: a.minor.saturating_add(b.minor), currency: a.currency })
}

pub fn subtract(a: Money, b: Money) -> Result<Money, CurrencyMismatch> {
    same(a, b)?;
    Ok(Money { minor: a.minor.saturating_sub(b.minor), currency: a.currency })
}

pub fn negate(m: Money) -> Money {
    Money { minor: -m.minor, currency: m.currency }
}

pub fn is_zero(m: Money) -> bool {
    m.minor == 0
}

pub fn is_negative(m: Money) -> bool {
    m.minor < 0
}

/// Total a list. The CURRENCY IS PASSED IN rather than taken from the first element, so an EMPTY
/// list has an answer — and a list that turns out to be mixed is an error rather than a total in
/// whichever currency happened to come first.
pub fn sum(items: &[Money], currency: Currency) -> Result<Money, CurrencyMismatch> {
    let mut total: Minor = 0;
    for m in items {
        if m.currency != currency {
            return Err(CurrencyMismatch { left: currency, right: m.currency });
        }
        total = total.saturating_add(m.minor);
    }
    Ok(Money { minor: total, currency })
}

/// How a fraction of a minor unit is resolved. STATED, never inherited from whatever a float did.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Rounding {
    HalfUp,
    HalfEven,
    Down,
    Up,
}

/// Apply a rate, rounding EXACTLY ONCE and in a way the caller chose.
///
/// The rate is a float because a rate genuinely is fractional; what matters is that the RESULT is an
/// integer and that the rounding is a decision rather than an accident.
pub fn scale(m: Money, rate: f64, rounding: Rounding) -> Money {
    Money { minor: round(m.minor as f64 * rate, rounding), currency: m.currency }
}

/// The rounding itself, and EVERY MODE HERE IS SYMMETRIC ABOUT ZERO.
///
/// That is the whole subtlety, and it is where a hand-port silently diverges. `half-up` means away
/// from zero, so −2.5 goes to −3 exactly as 2.5 goes to 3; `down` means toward zero (truncate), not
/// toward −∞; `up` means away from zero, not toward +∞. Using `floor`/`ceil` directly gets all three
/// backwards on negatives — and half the amounts in this feature are negative by the sign contract,
/// so it would be wrong on the common case rather than an edge one.
fn round(x: f64, mode: Rounding) -> Minor {
    let r = match mode {
        Rounding::Down => x.trunc(),
        Rounding::Up => {
            if x < 0.0 { x.floor() } else { x.ceil() }
        }
        Rounding::HalfEven => {
            // Banker's rounding — ties go to the EVEN neighbour, so a long series of .5 cases does
            // not drift upward the way half-up does. Written as one condition rather than a ladder
            // because two of the ladder's arms returned the same value.
            let f = x.floor();
            let diff = x - f;
            if diff > 0.5 || (diff == 0.5 && (f as i64) % 2 != 0) { f + 1.0 } else { f }
        }
        Rounding::HalfUp => {
            if x < 0.0 { -(-x).round() } else { x.round() }
        }
    };
    r as Minor
}

/// Split by weights so that the parts SUM EXACTLY BACK to the whole.
///
/// Largest-remainder: floor every share, then hand the leftover minor units out one at a time to
/// whoever was cut hardest. Rounding each share independently loses or invents money — a cent that
/// vanishes here is a reconciliation failure three modules away, with nothing to point at.
pub fn allocate(m: Money, weights: &[i64]) -> Result<Vec<Money>, String> {
    if weights.is_empty() {
        return Err("allocate needs at least one weight".to_string());
    }
    if weights.iter().any(|w| *w < 0) {
        return Err("allocate weights must be non-negative".to_string());
    }
    let total: i64 = weights.iter().sum();
    if total <= 0 {
        return Err("allocate weights must sum to more than zero".to_string());
    }

    // WORK ON THE MAGNITUDE, so a negative amount splits as the mirror of its positive twin rather
    // than having the remainder pushed the other way by flooring toward −∞.
    let sign: Minor = if m.minor < 0 { -1 } else { 1 };
    let magnitude = m.minor.abs();
    let mut shares: Vec<Minor> = weights.iter().map(|w| magnitude * w / total).collect();
    let mut remainder = magnitude - shares.iter().sum::<Minor>();
    let mut i = 0;
    while remainder > 0 {
        shares[i] += 1;
        remainder -= 1;
        i = (i + 1) % shares.len();
    }

    Ok(shares.into_iter().map(|s| Money { minor: sign * s, currency: m.currency }).collect())
}

/// `n` equal parts, losing nothing — the common case of {@link allocate}.
pub fn split(m: Money, n: usize) -> Result<Vec<Money>, String> {
    allocate(m, &vec![1; n])
}

#[cfg(test)]
mod tests {

    // ── the algebra, ported from money.ts ─────────────────────────────────────────────────────────

    fn eur() -> Currency {
        Currency::new("EUR").unwrap()
    }

    #[test]
    fn a_currency_is_three_letters_and_case_does_not_make_a_second_one() {
        assert_eq!(Currency::new("usd").unwrap(), Currency::USD);
        assert_eq!(Currency::USD.as_str(), "USD");
        for bad in ["US", "USDD", "US1", ""] {
            assert!(Currency::new(bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn adding_two_currencies_is_refused_rather_than_returning_a_number() {
        // Not a number problem — a modelling error, and returning a number would let it travel.
        let e = add(usd(100), money(100, eur())).unwrap_err();
        assert_eq!(e.left, Currency::USD);
        assert!(e.to_string().contains("convert first, explicitly"));
        assert!(subtract(usd(100), money(100, eur())).is_err());
    }

    #[test]
    fn the_ordinary_arithmetic_holds() {
        assert_eq!(add(usd(100), usd(250)).unwrap().minor, 350);
        assert_eq!(subtract(usd(100), usd(250)).unwrap().minor, -150);
        assert_eq!(negate(usd(100)).minor, -100);
        assert!(is_zero(usd(0)));
        assert!(is_negative(usd(-1)));
        assert!(!is_negative(usd(0)));
    }

    #[test]
    fn sum_takes_its_currency_so_an_empty_list_still_has_an_answer() {
        // Taking it from the first element would leave an empty list with no currency at all, and a
        // mixed list with whichever one happened to come first.
        assert_eq!(sum(&[], Currency::USD).unwrap().minor, 0);
        assert_eq!(sum(&[usd(100), usd(-40)], Currency::USD).unwrap().minor, 60);
        assert!(sum(&[usd(100), money(1, eur())], Currency::USD).is_err());
    }

    #[test]
    fn rounding_is_a_decision_and_each_mode_actually_differs() {
        // 2.5 is the tie every mode disagrees about, which is why it is the one worth pinning.
        assert_eq!(scale(usd(5), 0.5, Rounding::HalfUp).minor, 3);
        assert_eq!(scale(usd(5), 0.5, Rounding::Down).minor, 2);
        assert_eq!(scale(usd(5), 0.5, Rounding::Up).minor, 3);
        // Banker's rounding sends a tie to the EVEN neighbour: 2.5 -> 2, 3.5 -> 4.
        assert_eq!(scale(usd(5), 0.5, Rounding::HalfEven).minor, 2);
        assert_eq!(scale(usd(7), 0.5, Rounding::HalfEven).minor, 4);
    }

    #[test]
    fn every_rounding_mode_is_symmetric_about_zero() {
        // THE CASE A HAND-PORT GETS WRONG, and it is not an edge case here: half the amounts in this
        // feature are negative by the sign contract, so `floor`/`ceil` instead of trunc/away-from-
        // zero would be wrong on the COMMON path. Pinned against the TypeScript these came from.
        for (mode, pos, neg) in [
            (Rounding::HalfUp, 3, -3),
            (Rounding::Down, 2, -2),
            (Rounding::Up, 3, -3),
        ] {
            assert_eq!(scale(usd(5), 0.5, mode).minor, pos, "{mode:?} positive");
            assert_eq!(scale(usd(-5), 0.5, mode).minor, neg, "{mode:?} negative");
        }
    }

    #[test]
    fn scale_keeps_the_currency_and_handles_a_negative() {
        let m = scale(money(-1000, eur()), 0.25, Rounding::HalfUp);
        assert_eq!(m.currency, eur());
        assert_eq!(m.minor, -250);
    }

    #[test]
    fn allocate_loses_nothing_however_awkward_the_split() {
        // The whole point. Rounding each share independently loses or invents money, and a cent that
        // vanishes here is a reconciliation failure three modules away with nothing to point at.
        for total in [100, 101, 1, 999_983, -100, -7] {
            for weights in [vec![1, 1, 1], vec![1, 2, 3], vec![7, 1], vec![1]] {
                let parts = allocate(usd(total), &weights).unwrap();
                let back: i64 = parts.iter().map(|p| p.minor).sum();
                assert_eq!(back, total, "total {total} weights {weights:?} -> {parts:?}");
                assert_eq!(parts.len(), weights.len());
            }
        }
    }

    #[test]
    fn allocate_hands_the_remainder_out_from_the_front_and_mirrors_on_a_negative() {
        // Both halves are behaviour the TypeScript defines, not choices made here: the remainder
        // goes round-robin from index 0, and a negative splits as the mirror of its positive twin.
        let pos: Vec<i64> = allocate(usd(100), &[1, 1, 1]).unwrap().iter().map(|p| p.minor).collect();
        assert_eq!(pos, [34, 33, 33]);
        let neg: Vec<i64> = allocate(usd(-100), &[1, 1, 1]).unwrap().iter().map(|p| p.minor).collect();
        assert_eq!(neg, [-34, -33, -33]);
    }

    /// EVERY VALUE BELOW WAS TAKEN FROM THE TYPESCRIPT, by transpiling
    /// `@/features/finance/lib/money` and running it — not by reading it and reasoning about what it
    /// probably does. Reading it is how the first version of this port ended up with FOUR
    /// divergences, all of them on negatives, all of them silent: `half-up` rounding toward +∞
    /// instead of away from zero, `down` flooring instead of truncating, `up` ceiling instead of
    /// going away from zero, and `allocate` distributing by largest remainder instead of round-robin
    /// over the magnitude.
    ///
    /// Half the amounts in this feature are negative by the sign contract, so those were not edge
    /// cases — they were the common path. This table is what stops the two kits drifting again.
    #[test]
    fn the_port_matches_the_typescript_value_for_value() {
        let cases: &[(Rounding, i64, i64)] = &[
            (Rounding::HalfUp, 5, 3),
            (Rounding::HalfUp, -5, -3),
            (Rounding::HalfUp, 7, 4),
            (Rounding::HalfUp, -7, -4),
            (Rounding::HalfUp, 3, 2),
            (Rounding::HalfUp, -3, -2),
            (Rounding::Down, 5, 2),
            (Rounding::Down, -5, -2),
            (Rounding::Down, 7, 3),
            (Rounding::Down, -7, -3),
            (Rounding::Down, 3, 1),
            (Rounding::Down, -3, -1),
            (Rounding::Up, 5, 3),
            (Rounding::Up, -5, -3),
            (Rounding::Up, 7, 4),
            (Rounding::Up, -7, -4),
            (Rounding::Up, 3, 2),
            (Rounding::Up, -3, -2),
            (Rounding::HalfEven, 5, 2),
            (Rounding::HalfEven, -5, -2),
            (Rounding::HalfEven, 7, 4),
            (Rounding::HalfEven, -7, -4),
            (Rounding::HalfEven, 3, 2),
            (Rounding::HalfEven, -3, -2),
        ];
        for (mode, input, expected) in cases {
            assert_eq!(
                scale(usd(*input), 0.5, *mode).minor,
                *expected,
                "scale({input}, 0.5, {mode:?}) — the TypeScript says {expected}"
            );
        }

        let splits: &[(i64, &[i64], &[i64])] = &[
            (100, &[1, 1, 1], &[34, 33, 33]),
            (-100, &[1, 1, 1], &[-34, -33, -33]),
            (100, &[1, 2, 3], &[17, 33, 50]),
            (-7, &[1, 1], &[-4, -3]),
            (101, &[7, 1], &[89, 12]),
        ];
        for (amount, weights, expected) in splits {
            let got: Vec<i64> = allocate(usd(*amount), weights).unwrap().iter().map(|m| m.minor).collect();
            assert_eq!(got, *expected, "allocate({amount}, {weights:?}) — the TypeScript says {expected:?}");
        }
    }

    #[test]
    fn allocate_refuses_what_is_not_a_split() {
        assert!(allocate(usd(100), &[]).is_err());
        assert!(allocate(usd(100), &[0, 0]).is_err());
        assert!(allocate(usd(100), &[-1, 2]).is_err());
    }

    #[test]
    fn split_is_allocate_with_equal_weights_and_still_loses_nothing() {
        let parts = split(usd(100), 3).unwrap();
        assert_eq!(parts.iter().map(|p| p.minor).sum::<i64>(), 100);
        assert_eq!(split(usd(-100), 7).unwrap().iter().map(|p| p.minor).sum::<i64>(), -100);
    }

    use super::*;

    /// EVERY FIXTURE HERE IS SYNTHETIC. No real statement, balance or account number belongs in this
    /// repo — the maintainer's data stays on the maintainer's machine, which is the whole premise of
    /// this crate.
    #[test]
    fn reads_the_shapes_statements_actually_print() {
        assert_eq!(parse_minor("1234.56").unwrap(), 123456);
        assert_eq!(parse_minor("$1,234.56").unwrap(), 123456);
        assert_eq!(parse_minor("-1234.56").unwrap(), -123456);
        assert_eq!(parse_minor("  1234.56  ").unwrap(), 123456);
        // Whole units with no decimal part at all.
        assert_eq!(parse_minor("1234").unwrap(), 123400);
        // One decimal digit means TENTHS, not hundredths — `1234.5` is $1234.50, not $12.345.
        assert_eq!(parse_minor("1234.5").unwrap(), 123450);
    }

    #[test]
    fn honours_both_negative_conventions() {
        // Accounting parentheses and a TRAILING sign are both real. Reading either as a stray
        // character would flip a refund into a charge, and the balance would be wrong by twice it.
        assert_eq!(parse_minor("(1234.56)").unwrap(), -123456);
        assert_eq!(parse_minor("1234.56-").unwrap(), -123456);
        assert_eq!(parse_minor("($1,234.56)").unwrap(), -123456);
    }

    #[test]
    fn is_exact_where_a_float_would_not_be() {
        // `"0.07".parse::<f64>() * 100.0` is 7.000000000000001. Reading the fraction as an integer
        // makes the value exact by construction rather than by luck at the rounding boundary.
        assert_eq!(parse_minor("0.07").unwrap(), 7);
        assert_eq!(parse_minor("0.29").unwrap(), 29);
        assert_eq!(parse_minor("1.10").unwrap(), 110);
        for cents in 0..100 {
            let s = format!("0.{cents:02}");
            assert_eq!(parse_minor(&s).unwrap(), cents, "{s} must be exact");
        }
    }

    #[test]
    fn truncates_a_third_decimal_rather_than_inventing_a_cent() {
        // A statement printing three decimals has a sub-cent artifact. Rounding it up would put a
        // figure in the store that is not on the statement, and reconciliation would fail against
        // the source rather than against the arithmetic.
        assert_eq!(parse_minor("1.999").unwrap(), 199);
        assert_eq!(parse_minor("-1.999").unwrap(), -199);
    }

    #[test]
    fn refuses_what_it_cannot_read_rather_than_guessing() {
        // A row that silently becomes zero is a missing transaction, which is a wrong balance that
        // nobody can find. Every one of these must be reported to the caller.
        assert!(parse_minor("").is_err());
        assert!(parse_minor("   ").is_err());
        assert!(parse_minor("N/A").is_err());
        assert!(parse_minor("--").is_err());
        assert!(parse_minor("1.2.3").is_err());
        assert!(parse_minor("12 34 abc").is_err());
    }

    #[test]
    fn round_trips_through_display() {
        for v in [0i64, 7, -7, 100, -100, 123456, -123456, 999999999] {
            assert_eq!(parse_minor(&format_minor(v)).unwrap(), v, "{v}");
        }
        assert_eq!(format_minor(-7), "-0.07");
        assert_eq!(format_minor(123456), "1234.56");
    }
}

